_SOURCES = json.loads(
    zlib.decompress(
        base64.b85decode(_BUNDLE)
    ).decode("utf-8")
)


class _StyleTTS2Loader(importlib.abc.Loader):
    def __init__(self, fullname):
        self.fullname = fullname

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        module.__file__ = (
            "<embedded-styletts2>/" +
            self.fullname.replace(".", "/") +
            ".py"
        )
        exec(
            compile(
                _SOURCES[self.fullname],
                module.__file__,
                "exec",
            ),
            module.__dict__,
        )


class _StyleTTS2Finder(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _SOURCES:
            return None

        is_package = (
            fullname + "." in
            [name[:len(fullname) + 1] for name in _SOURCES]
        )

        return importlib.util.spec_from_loader(
            fullname,
            _StyleTTS2Loader(fullname),
            is_package=is_package,
        )


if not any(
    isinstance(finder, _StyleTTS2Finder)
    for finder in sys.meta_path
):
    sys.meta_path.insert(0, _StyleTTS2Finder())


from Model.models import (
    build_model,
    load_ASR_models,
    load_F0_models,
)
from Model.Utils.PLBERT.util import load_plbert
from Model.losses import MultiResolutionSTFTLoss
from common.utils import recursive_munch


ROOT = Path(__file__).resolve().parents[1]


def resolve_path(path):
    import os

    path = os.path.expandvars(str(path))

    if "${STYLETTS2_ASSETS}" in path:
        raise RuntimeError("STYLETTS2_ASSETS is not set")

    p = Path(path).expanduser()
    return str(p if p.is_absolute() else ROOT / p)


def build_styletts2(config):
    text_aligner = load_ASR_models(
        resolve_path(config["ASR_path"]),
        resolve_path(config["ASR_config"]),
    )

    pitch_extractor = load_F0_models(
        resolve_path(config["F0_path"])
    )

    plbert = load_plbert(
        resolve_path(config["PLBERT_dir"])
    )

    params = recursive_munch(config["model_params"])

    return build_model(
        params,
        text_aligner,
        pitch_extractor,
        plbert,
    )
